16	  const tipY = (R_OUT * R_OUT - R_IN * R_IN + OFFSET * OFFSET) / (2 * OFFSET);
17	  const tipX = Math.sqrt(Math.max(0, R_OUT * R_OUT - tipY * tipY));
18	  const outerStart = Math.atan2(tipY, tipX);
19	  const outerSpan  = -(2 * Math.PI - (Math.atan2(tipY, -tipX) - outerStart));
20	  const innerStart = Math.atan2(tipY - OFFSET, -tipX);
21	  const innerSpan  = 2 * Math.PI - (innerStart - Math.atan2(tipY - OFFSET, tipX));
22	  const pts: Phaser.Geom.Point[] = [];
23	  for (let i = 0; i <= STEPS; i++) {
24	    const a = outerStart + outerSpan * (i / STEPS);
25	    pts.push(new Phaser.Geom.Point(Math.cos(a) * R_OUT, Math.sin(a) * R_OUT));
26	  }
27	  for (let i = 0; i <= STEPS; i++) {
28	    const a = innerStart + innerSpan * (i / STEPS);
29	    pts.push(new Phaser.Geom.Point(Math.cos(a) * R_IN, Math.sin(a) * R_IN + OFFSET));
30	  }
31	  return pts;
32	})();
