1	import Phaser from 'phaser';
2	import { BaseAbility } from './BaseAbility';
3	import type { GameSceneAPI } from './types';
4	import type PoolablePoopBase from '../objects/PoolablePoopBase';
5	import { SENTINEL_PARAMS } from '../config/abilityParams';
6	
7	/**
8	 * 센티넬 (UR) — 보호막
9	 * ★0: 2개 시작 / 300점마다 충전 / 최대 3  / ★1: 2개 / 250점마다 / 최대 4
10	 * ★2: 3개 시작 / 200점마다 충전 / 최대 4  / ★3: 3개 / 150점마다 / 최대 5 + 흡수 시 연쇄 전기 3개 추가 제거
11	 * - UI: 붉은 공이 허리 주변 수평 궤도 공전 + 전기 파지직 (재사용 Graphics)
12	 */
13	export class SentinelAbility extends BaseAbility {
14	  private shieldCount = 0;
15	  private orbitDroplets: Phaser.GameObjects.Graphics[] = [];
16	  private orbitAngle = 0;
17	
18	  // ── 전기 스파크: persistent Graphics 재사용 (동적 생성 없음) ──
19	  private sparkGfx: Phaser.GameObjects.Graphics | null = null;
20	  private sparkTween: Phaser.Tweens.Tween | null = null;
21	  private sparkTimer = 0;
22	
23	  private static readonly ORBIT_SPEED   = 3.0;
24	  private static readonly ORBIT_RX      = 26;
25	  private static readonly ORBIT_RY      = 7;
26	  private static readonly ORBIT_WAIST_Y = 8;
27	  private static readonly RED           = 0xff2222;
28	  private static readonly RED_LIGHT     = 0xff6666;
29	
30	  override onCreate(api: GameSceneAPI): void {
31	    this.shieldCount = SENTINEL_PARAMS.startShields;
32	    this.spawnDroplets(api, SENTINEL_PARAMS.startShields);
33	    this.sparkGfx = api.scene.add.graphics().setDepth(96).setAlpha(0);
34	  }
35	
36	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
37	    if (score % SENTINEL_PARAMS.chargeInterval === 0 && this.shieldCount < SENTINEL_PARAMS.maxShields) {
38	      this.shieldCount++;
39	      this.playShieldChargeEffect(api);
40	      this.spawnDroplets(api, 1);
41	    }
42	  }
43	
44	  override onHitPoop(api: GameSceneAPI): boolean {
45	    if (this.shieldCount > 0) {
46	      this.shieldCount--;
47	      this.scatterDroplets(api, 1);
48	      this.playShieldBreakEffect(api);
49	      this.zapNearbyPoops(api, 320);
50	      return true;
51	    }
52	    return false;
53	  }
54	
55	  override onUpdate(api: GameSceneAPI): void {
56	    if (this.orbitDroplets.length === 0) return;
57	
58	    const delta  = api.scene.game.loop.delta / 1000;
59	    const deltMs = api.scene.game.loop.delta;
60	    this.orbitAngle += SentinelAbility.ORBIT_SPEED * delta;
61	
62	    const cx    = api.player.x;
63	    const cy    = api.player.y + SentinelAbility.ORBIT_WAIST_Y;
64	    const total = this.orbitDroplets.length;
65	    const RX    = SentinelAbility.ORBIT_RX;
66	    const RY    = SentinelAbility.ORBIT_RY;
67	
68	    this.orbitDroplets.forEach((drop, i) => {
69	      if (!drop.active) return;
70	      const angle = this.orbitAngle + (i / total) * Math.PI * 2;
71	      const sinA  = Math.sin(angle);
72	
73	      drop.setPosition(cx + Math.cos(angle) * RX, cy + sinA * RY);
74	
75	      const t = (sinA + 1) / 2;
76	      drop.setScale(0.55 + 0.55 * t);
77	      drop.setAlpha(0.35 + 0.65 * t);
78	      drop.setDepth(sinA > 0 ? 101 : 89);
79	    });
80	
81	    // 전기 파지직: 250ms마다 persistent sparkGfx를 clear+redraw
82	    this.sparkTimer += deltMs;
83	    if (this.sparkTimer >= 250) {
84	      this.sparkTimer = 0;
85	      this.redrawSparks(api);
86	    }
87	  }
88	
89	  // ─────────────────────────────────────────────────────────────
90	  // 리소스 정리 (게임 오버 시 GameScene에서 호출)
91	  // ─────────────────────────────────────────────────────────────
92	
93	  override onDestroy(_api: GameSceneAPI): void {
94	    this.sparkTween?.stop();
95	    this.sparkGfx?.destroy();
96	    this.orbitDroplets.forEach(drop => drop.destroy());
97	  }
98	
99	  // ─────────────────────────────────────────────────────────────
100	  // 전기 스파크 (재사용 Graphics)
101	  // ─────────────────────────────────────────────────────────────
102	
103	  /** persistent sparkGfx를 clear 후 몸+공 스파크를 새로 그리고 alpha tween */
104	  private redrawSparks(api: GameSceneAPI): void {
105	    const g = this.sparkGfx;
106	    if (!g?.active) return;
107	
108	    g.clear();
109	    g.setAlpha(1);
110	    this.sparkTween?.stop();
111	
112	    // 몸 주변 스파크 (굵게)
113	    const ba    = Phaser.Math.FloatBetween(0, Math.PI * 2);
114	    const br    = Phaser.Math.FloatBetween(18, 34);
115	    this.drawSparkLine(g, api.player.x + Math.cos(ba) * br, api.player.y + Math.sin(ba) * br * 0.6, 2.5, 10);
116	
117	    // 공 주변 스파크 (가늘게, 40% 확률 per droplet)
118	    this.orbitDroplets.forEach(drop => {
119	      if (drop.active && drop.alpha > 0.5 && Math.random() < 0.4) {
120	        this.drawSparkLine(g, drop.x, drop.y, 1, 7);
121	      }
122	    });
123	
124	    this.sparkTween = api.scene.tweens.add({
125	      targets: g,
126	      alpha: 0,
127	      duration: 200,
128	      ease: 'Quad.easeOut',
129	    });
130	  }
131	
132	  /** 전달받은 Graphics에 지그재그 라인을 직접 그림 (새 객체 생성 없음) */
133	  private drawSparkLine(g: Phaser.GameObjects.Graphics, ox: number, oy: number, thickness: number, segLen: number): void {
134	    const color = Math.random() < 0.6 ? 0xff3333 : 0xff7744;
135	    g.lineStyle(thickness, color, 1);
136	    g.beginPath();
137	    let px = ox + Phaser.Math.Between(-5, 5);
138	    let py = oy + Phaser.Math.Between(-5, 5);
139	    g.moveTo(px, py);
140	    const segs = Phaser.Math.Between(2, 4);
141	    for (let j = 0; j < segs; j++) {
142	      px += Phaser.Math.Between(-segLen, segLen);
143	      py += Phaser.Math.Between(-segLen, segLen);
144	      g.lineTo(px, py);
145	    }
146	    g.strokePath();
147	  }
148	
149	  // ─────────────────────────────────────────────────────────────
150	  // 방울 관리
151	  // ─────────────────────────────────────────────────────────────
152	
153	  private spawnDroplets(api: GameSceneAPI, count: number): void {
154	    const scene = api.scene;
155	    for (let i = 0; i < count; i++) {
156	      const g = scene.add.graphics().setDepth(95);
157	      this.drawDroplet(g);
158	      g.setPosition(api.player.x, api.player.y + SentinelAbility.ORBIT_WAIST_Y);
159	      g.setAlpha(0);
160	      this.orbitDroplets.push(g);
161	      scene.tweens.add({ targets: g, alpha: 1, scaleX: 1, scaleY: 1, duration: 350, delay: i * 50, ease: 'Back.easeOut' });
162	    }
