3	import type { GameSceneAPI } from './types';
4	import type PoolablePoopBase from '../objects/PoolablePoopBase';
5	import { HACKER_PARAMS } from '../config/abilityParams';
6	
7	/**
8	 * 루트 (SR) — 터미널 삭제
9	 * 수치: HACKER_PARAMS 참조
10	 */
11	export class HackerAbility extends BaseAbility {
12	  private lastHackerScore = 0;
13	
14	  override specialPoopSpeedReduction(_type: 'gold' | 'diamond'): number {
15	    return HACKER_PARAMS.specialPoopSlowdown;
16	  }
17	
18	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
19	    if (score % HACKER_PARAMS.deleteInterval === 0 && score > this.lastHackerScore) {
20	      this.lastHackerScore = score;
21	      this.removeRandomPoops(HACKER_PARAMS.deleteCount, api);
22	    }
23	  }
24	
25	  private removeRandomPoops(count: number, api: GameSceneAPI): void {
26	    const active = api.poops
27	      .getChildren()
28	      .filter(p => (p as Phaser.GameObjects.GameObject).active) as Phaser.Physics.Arcade.Sprite[];
29	
30	    active.sort(() => Math.random() - 0.5);
31	    active.slice(0, count).forEach(p => {
32	      this.playTerminalEffect(p.x, p.y, api);
33	      (p as PoolablePoopBase).recycle();
34	    });
35	  }
36	
37	  /** 초록 테두리 검정 박스 flash → 픽셀 비산 */
38	  private playTerminalEffect(cx: number, cy: number, api: GameSceneAPI): void {
39	    const scene = api.scene;
40	    const BOX_W = 36, BOX_H = 36;
41	
