import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { KNIGHT_PARAMS } from '../config/abilityParams';

const R_OUT  = 26;
const R_IN   = 20;
const OFFSET = 12;
const STEPS  = 30;

interface WaveCfg { scale: number; speed: number; amp: number; phase: number; }

// 형상이 고정이므로 모듈 초기화 시 한 번만 계산
const BASE_PTS: Phaser.Geom.Point[] = (() => {
  const tipY = (R_OUT * R_OUT - R_IN * R_IN + OFFSET * OFFSET) / (2 * OFFSET);
  const tipX = Math.sqrt(Math.max(0, R_OUT * R_OUT - tipY * tipY));
  const outerStart = Math.atan2(tipY, tipX);
  const outerSpan  = -(2 * Math.PI - (Math.atan2(tipY, -tipX) - outerStart));
  const innerStart = Math.atan2(tipY - OFFSET, -tipX);
  const innerSpan  = 2 * Math.PI - (innerStart - Math.atan2(tipY - OFFSET, tipX));
  const pts: Phaser.Geom.Point[] = [];
  for (let i = 0; i <= STEPS; i++) {
    const a = outerStart + outerSpan * (i / STEPS);
    pts.push(new Phaser.Geom.Point(Math.cos(a) * R_OUT, Math.sin(a) * R_OUT));
  }
  for (let i = 0; i <= STEPS; i++) {
    const a = innerStart + innerSpan * (i / STEPS);
    pts.push(new Phaser.Geom.Point(Math.cos(a) * R_IN, Math.sin(a) * R_IN + OFFSET));
  }
  return pts;
})();

// 프레임당 재사용할 Point 버퍼 — new Point() 할당 없이 in-place 덮어쓰기
// JS는 단일 스레드 + tween onUpdate 순차 실행이므로 레이어별 버퍼 1개로 충분
const _bufs = {
  outer: BASE_PTS.map(() => new Phaser.Geom.Point()),
  mid:   BASE_PTS.map(() => new Phaser.Geom.Point()),
  body:  BASE_PTS.map(() => new Phaser.Geom.Point()),
};

export class KnightAbility extends BaseAbility {
  private lastBeamScore = 0;

  // onDestroy 시 정리할 리소스 추적
  private activeTimers: Phaser.Time.TimerEvent[]       = [];
  private activeGraphics: Phaser.GameObjects.Graphics[] = [];

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % KNIGHT_PARAMS.beamInterval === 0 && score > this.lastBeamScore) {
      this.lastBeamScore = score;
      [-30, 0, 30].forEach(deg => this.fireSingleCrescent(api, deg));
    }
  }

  override onDestroy(api: GameSceneAPI): void {
    this.activeTimers.forEach(t => t.destroy());
    this.activeTimers = [];
    this.activeGraphics.forEach(g => {
      api.scene.tweens.killTweensOf(g);
      if (g.active) g.destroy();
    });
    this.activeGraphics = [];
  }

  private wavyPoints(buf: Phaser.Geom.Point[], time: number, cfg: WaveCfg): Phaser.Geom.Point[] {
    BASE_PTS.forEach((p, i) => {
      const r = Math.hypot(p.x, p.y);
      const wave = Math.sin(time * cfg.speed + i * 0.32 + cfg.phase) * cfg.amp;
      const s = r > 0.1 ? (r * cfg.scale + wave) / r : cfg.scale;
      buf[i].x = p.x * s;
      buf[i].y = p.y * s;
    });
    return buf;
  }

  private fireSingleCrescent(api: GameSceneAPI, rotationDeg: number): void {
    const scene  = api.scene;
    const px     = api.player.x;
    const py     = api.player.y - 20;
    const rotRad = rotationDeg * (Math.PI / 180);
    const dx     = Math.sin(rotRad);
    const dy     = -Math.cos(rotRad);
    const TRAVEL = py + 80;
    const duration = (TRAVEL / 520) * 1000;

    const makeGfx = (depth: number): Phaser.GameObjects.Graphics => {
      const g = scene.add.graphics().setDepth(depth).setPosition(px, py).setRotation(rotRad);
      this.activeGraphics.push(g);
      return g;
    };

    const outerGlow = makeGfx(118);
    const midGlow   = makeGfx(119);
    const body      = makeGfx(120);
    const edge      = makeGfx(121);
    const all       = [outerGlow, midGlow, body, edge];


    const particleTimer = scene.time.addEvent({
      delay: 45,
      loop: true,
      callback: () => {
        if (!body.active) return;
        const bp = BASE_PTS[Phaser.Math.Between(0, BASE_PTS.length - 1)];
        const cos = Math.cos(rotRad), sin = Math.sin(rotRad);
        const wx = body.x + bp.x * cos - bp.y * sin;
        const wy = body.y + bp.x * sin + bp.y * cos;
        this.spawnSpark(scene, wx, wy, {
          color: Phaser.Math.Between(0, 1) ? 0xff9900 : 0xffcc44,
          radius: Phaser.Math.FloatBetween(1, 3),
          tx: wx + Phaser.Math.FloatBetween(-12, 12),
          ty: wy + Phaser.Math.FloatBetween(-18, 4),
          duration: Phaser.Math.Between(180, 320),
          endScale: 0.2,
        });
      },
    });
    this.activeTimers.push(particleTimer);

    const hitSet = new Set<Phaser.Physics.Arcade.Sprite>();
    const HIT_RADIUS = R_OUT + 10;

    scene.tweens.add({
      targets: all,
      x: `+=${dx * TRAVEL}`,
      y: `+=${dy * TRAVEL}`,
      duration,
      ease: 'Linear',
      onUpdate: () => {
        const t  = scene.time.now;
        outerGlow.clear();
        outerGlow.fillStyle(0xff6600, 0.12 + Math.sin(t * 0.011) * 0.07);
        outerGlow.fillPoints(this.wavyPoints(_bufs.outer, t, { scale: 1.65, speed: 0.007, amp: 5.5, phase: 0 }), true);

        midGlow.clear();
        midGlow.fillStyle(0xff8800, 0.28 + Math.sin(t * 0.014 + 1.2) * 0.1);
        midGlow.fillPoints(this.wavyPoints(_bufs.mid, t, { scale: 1.25, speed: 0.01, amp: 3.5, phase: 1.0 }), true);

        const bodyPts = this.wavyPoints(_bufs.body, t, { scale: 1.0, speed: 0.013, amp: 2.5, phase: 2.1 });

        body.clear();
        body.fillStyle(0xffaa44, 0.92);
        body.fillPoints(bodyPts, true);

        // body와 동일 파형 → 캐시된 bodyPts 재사용
        edge.clear();
        edge.lineStyle(2, 0xffeecc, 0.9);
        edge.strokePoints(bodyPts, true);

        const cx = body.x, cy = body.y;
        (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[]).forEach(sp => {
          if (!sp.active || hitSet.has(sp)) return;
          if (Phaser.Math.Distance.Between(cx, cy, sp.x, sp.y) <= HIT_RADIUS) {
            hitSet.add(sp);
            for (let i = 0; i < 7; i++) {
              const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
              const dist  = Phaser.Math.Between(10, 28);
              this.spawnSpark(scene, sp.x, sp.y, {
                color: 0xffaa55,
                radius: Phaser.Math.Between(2, 5),
                tx: sp.x + Math.cos(angle) * dist,
                ty: sp.y + Math.sin(angle) * dist - 8,
                duration: Phaser.Math.Between(180, 380),
              });
            }
            (sp as PoolablePoopBase).recycle();
            api.addAbilityBonus(KNIGHT_PARAMS.beamKillBonus);
          }
        });
      },
      onComplete: () => {
        particleTimer.destroy();
        this.activeTimers = this.activeTimers.filter(t => t !== particleTimer);
        all.forEach(g => {
          this.activeGraphics = this.activeGraphics.filter(ag => ag !== g);
          g.destroy();
        });
      },
    });
  }

  private spawnSpark(
    scene: Phaser.Scene,
    x: number, y: number,
    opts: { color: number; radius: number; tx: number; ty: number; duration: number; endScale?: number },
  ): void {
    const g = scene.add.graphics().setDepth(122).setPosition(x, y);
    g.fillStyle(opts.color, 1);
    g.fillCircle(0, 0, opts.radius);
    const tween: Phaser.Types.Tweens.TweenBuilderConfig = {
      targets: g, x: opts.tx, y: opts.ty, alpha: 0,
      duration: opts.duration, ease: 'Quad.easeOut',
      onComplete: () => g.destroy(),
    };
    if (opts.endScale !== undefined) {
      (tween as Record<string, unknown>).scaleX = opts.endScale;
      (tween as Record<string, unknown>).scaleY = opts.endScale;
    }
    scene.tweens.add(tween);
  }
}

import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { MAEHWA_PARAMS } from '../config/abilityParams';

/**
 * 매화 (SR) — 이동속도 버프 / 점수마다 칼 베기
 * 수치: MAEHWA_PARAMS 참조
 */
export class MaehwaAbility extends BaseAbility {
  private lastMaehwaScore = 0;

  override getPlayerSpeedBonus(): number {
    return MAEHWA_PARAMS.speedBonus;
  }

  // ★2+: 특수 똥 수집 시 추가 점수 (MAEHWA_PARAMS.awake2SpecialBonus)
  override onCollectSpecial(_type: import('./types').SpecialPoopType): number {
    return this.awakeningLevel >= 2 ? MAEHWA_PARAMS.awake2SpecialBonus : 0;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % MAEHWA_PARAMS.slashInterval === 0 && score > this.lastMaehwaScore) {
      this.lastMaehwaScore = score;
      this.slashClosestPoops(MAEHWA_PARAMS.slashCount, api);
    }
  }

  private slashClosestPoops(count: number, api: GameSceneAPI): void {
    const active = api.poops
      .getChildren()
      .filter(p => {
        const sp = p as Phaser.Physics.Arcade.Sprite;
        return sp.active && sp.y < api.player.y;
      }) as Phaser.Physics.Arcade.Sprite[];

    active.sort((a, b) => {
      const da = Phaser.Math.Distance.Between(api.player.x, api.player.y, a.x, a.y);
      const db = Phaser.Math.Distance.Between(api.player.x, api.player.y, b.x, b.y);
      return da - db;
    });

    active.slice(0, count).forEach(poop => {
      this.drawSlashEffect(poop.x, poop.y, api);
      this.spawnPetals(poop.x, poop.y, api);
      (poop as PoolablePoopBase).recycle();
    });
  }

  /** 가운데가 넓은 대각선(↗) 칼날 이펙트 */
  private drawSlashEffect(cx: number, cy: number, api: GameSceneAPI): void {
    const gfx = api.scene.add.graphics().setDepth(120);

    // 칼날: fillPoints로 ↗ 방향 마름모꼴 (끝은 뾰족, 중앙은 넓음)
    const len = 26; // 반길이
    const wid = 7;  // 중앙 최대 반폭
    // ↗ 방향 slash: (cx-len, cy+len) → (cx+len, cy-len) 축
    gfx.fillStyle(0xff3366, 0.9);
    gfx.fillPoints([
      new Phaser.Geom.Point(cx - len, cy + len),          // 좌하 끝
      new Phaser.Geom.Point(cx - wid * 0.4, cy + wid),    // 좌상 측면
      new Phaser.Geom.Point(cx + len, cy - len),          // 우상 끝
      new Phaser.Geom.Point(cx + wid * 0.4, cy - wid),    // 우하 측면
    ], true);

    // 외곽 흰색 글로우
    gfx.lineStyle(3, 0xffffff, 0.5);
    gfx.lineBetween(cx - len, cy + len, cx + len, cy - len);

    gfx.postFX.addGlow(0xff3366, 14, 2, false, 0.1, 18);

    api.scene.tweens.add({
      targets: gfx,
      alpha: 0,
      duration: 300,
      onComplete: () => gfx.destroy(),
    });
  }

  /** 붉은 매화 잎 여러 개 낙화 */
  private spawnPetals(cx: number, cy: number, api: GameSceneAPI): void {
    const PETAL_COUNT = 7;
    for (let i = 0; i < PETAL_COUNT; i++) {
      const petal = api.scene.add.graphics().setDepth(121);
      // 초기 위치: 파괴된 똥 주변 랜덤
      const startX = cx + Phaser.Math.Between(-12, 12);
      const startY = cy + Phaser.Math.Between(-12, 12);
      petal.setPosition(startX, startY);

      // 작은 타원형 꽃잎
      const petalW = Phaser.Math.Between(4, 7);
      const petalH = Phaser.Math.Between(7, 11);
      petal.fillStyle(0xff2255, 0.85 + Math.random() * 0.15);
      petal.fillEllipse(0, 0, petalW, petalH);
      petal.setAngle(Phaser.Math.Between(0, 360));
      petal.postFX.addGlow(0xff2255, 5, 0, false, 0.1, 8);

      // 바람에 날리며 낙하
      api.scene.tweens.add({
        targets: petal,
        x: startX + Phaser.Math.Between(-25, 25),
        y: startY + Phaser.Math.Between(30, 60),
        angle: petal.angle + Phaser.Math.Between(-120, 120),
        alpha: 0,
        duration: Phaser.Math.Between(400, 700),
        ease: 'Sine.easeIn',
        onComplete: () => petal.destroy(),
      });
    }
  }
}

import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { HACKER_PARAMS } from '../config/abilityParams';

/**
 * 루트 (SR) — 터미널 삭제
 * 수치: HACKER_PARAMS 참조
 */
export class HackerAbility extends BaseAbility {
  private lastHackerScore = 0;

  override specialPoopSpeedReduction(_type: 'gold' | 'diamond'): number {
    return HACKER_PARAMS.specialPoopSlowdown;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % HACKER_PARAMS.deleteInterval === 0 && score > this.lastHackerScore) {
      this.lastHackerScore = score;
      this.removeRandomPoops(HACKER_PARAMS.deleteCount, api);
    }
  }

  private removeRandomPoops(count: number, api: GameSceneAPI): void {
    const active = api.poops
      .getChildren()
      .filter(p => (p as Phaser.GameObjects.GameObject).active) as Phaser.Physics.Arcade.Sprite[];

    active.sort(() => Math.random() - 0.5);
    active.slice(0, count).forEach(p => {
      this.playTerminalEffect(p.x, p.y, api);
      (p as PoolablePoopBase).recycle();
    });
  }

  /** 초록 테두리 검정 박스 flash → 픽셀 비산 */
  private playTerminalEffect(cx: number, cy: number, api: GameSceneAPI): void {
    const scene = api.scene;
    const BOX_W = 36, BOX_H = 36;

    const box = scene.add.graphics().setDepth(110);
    box.fillStyle(0x000000, 1);
    box.fillRect(-BOX_W / 2, -BOX_H / 2, BOX_W, BOX_H);
    box.lineStyle(2, 0x00ff41, 1);
    box.strokeRect(-BOX_W / 2, -BOX_H / 2, BOX_W, BOX_H);
    box.setPosition(cx, cy);
    box.postFX.addGlow(0x00ff41, 12, 0, false, 0.1, 18);

    scene.tweens.add({
      targets: box,
      alpha: 0,
      duration: 180,
      delay: 60,
      onComplete: () => box.destroy(),
    });

    const PIXEL_COUNT = 6;
    const GREEN = 0x00ff41;

    for (let i = 0; i < PIXEL_COUNT; i++) {
      const size  = Phaser.Math.Between(4, 9);
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const speed = Phaser.Math.FloatBetween(40, 110);
      const tx    = cx + Math.cos(angle) * speed;
      const ty    = cy + Math.sin(angle) * speed;

      const px = scene.add.graphics().setDepth(111);
      px.fillStyle(GREEN, 1);
      px.fillRect(0, 0, size, size);
      px.setPosition(cx, cy);
      px.postFX.addGlow(0x00ff41, 6, 0, false, 0.1, 8);

      scene.tweens.add({
        targets: px,
        x: tx,
        y: ty + Phaser.Math.Between(10, 30),
        alpha: 0,
        duration: Phaser.Math.Between(250, 420),
        ease: 'Quad.easeOut',
        onComplete: () => px.destroy(),
      });
    }
  }
}

