import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { KNIGHT_PARAMS } from '../config/abilityParams';

const R_OUT  = 26;
const R_IN   = 20;
const OFFSET = 12;
const STEPS  = 30;

interface WaveCfg { scale: number; speed: number; amp: number; phase: number; }

// 형상이 고정이므로 모듈 초기화 시 한 번만 계산
const BASE_PTS: Phaser.Geom.Point[] = (() => {
  const tipY = (R_OUT * R_OUT - R_IN * R_IN + OFFSET * OFFSET) / (2 * OFFSET);
  const tipX = Math.sqrt(Math.max(0, R_OUT * R_OUT - tipY * tipY));
  const outerStart = Math.atan2(tipY, tipX);
  const outerSpan  = -(2 * Math.PI - (Math.atan2(tipY, -tipX) - outerStart));
  const innerStart = Math.atan2(tipY - OFFSET, -tipX);
  const innerSpan  = 2 * Math.PI - (innerStart - Math.atan2(tipY - OFFSET, tipX));
  const pts: Phaser.Geom.Point[] = [];
  for (let i = 0; i <= STEPS; i++) {
    const a = outerStart + outerSpan * (i / STEPS);
    pts.push(new Phaser.Geom.Point(Math.cos(a) * R_OUT, Math.sin(a) * R_OUT));
  }
  for (let i = 0; i <= STEPS; i++) {
    const a = innerStart + innerSpan * (i / STEPS);
    pts.push(new Phaser.Geom.Point(Math.cos(a) * R_IN, Math.sin(a) * R_IN + OFFSET));
  }
  return pts;
})();

// 프레임당 재사용할 Point 버퍼 — new Point() 할당 없이 in-place 덮어쓰기
// JS는 단일 스레드 + tween onUpdate 순차 실행이므로 레이어별 버퍼 1개로 충분
const _bufs = {
  outer: BASE_PTS.map(() => new Phaser.Geom.Point()),
  mid:   BASE_PTS.map(() => new Phaser.Geom.Point()),
  body:  BASE_PTS.map(() => new Phaser.Geom.Point()),
};

export class KnightAbility extends BaseAbility {
  private lastBeamScore = 0;

  // onDestroy 시 정리할 리소스 추적
  private activeTimers: Phaser.Time.TimerEvent[]       = [];
  private activeGraphics: Phaser.GameObjects.Graphics[] = [];

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % KNIGHT_PARAMS.beamInterval === 0 && score > this.lastBeamScore) {
      this.lastBeamScore = score;
      [-30, 0, 30].forEach(deg => this.fireSingleCrescent(api, deg));
    }
  }

  override onDestroy(api: GameSceneAPI): void {
    this.activeTimers.forEach(t => t.destroy());
    this.activeTimers = [];
    this.activeGraphics.forEach(g => {
      api.scene.tweens.killTweensOf(g);
      if (g.active) g.destroy();
    });
    this.activeGraphics = [];
  }

  private wavyPoints(buf: Phaser.Geom.Point[], time: number, cfg: WaveCfg): Phaser.Geom.Point[] {
    BASE_PTS.forEach((p, i) => {
      const r = Math.hypot(p.x, p.y);
      const wave = Math.sin(time * cfg.speed + i * 0.32 + cfg.phase) * cfg.amp;
      const s = r > 0.1 ? (r * cfg.scale + wave) / r : cfg.scale;
      buf[i].x = p.x * s;
      buf[i].y = p.y * s;
    });
    return buf;
  }

  private fireSingleCrescent(api: GameSceneAPI, rotationDeg: number): void {
    const scene  = api.scene;
    const px     = api.player.x;
    const py     = api.player.y - 20;
    const rotRad = rotationDeg * (Math.PI / 180);
    const dx     = Math.sin(rotRad);
    const dy     = -Math.cos(rotRad);
    const TRAVEL = py + 80;
    const duration = (TRAVEL / 520) * 1000;

    const makeGfx = (depth: number): Phaser.GameObjects.Graphics => {
      const g = scene.add.graphics().setDepth(depth).setPosition(px, py).setRotation(rotRad);
      this.activeGraphics.push(g);
      return g;
    };

    const outerGlow = makeGfx(118);
    const midGlow   = makeGfx(119);
    const body      = makeGfx(120);
    const edge      = makeGfx(121);
    const all       = [outerGlow, midGlow, body, edge];


    const particleTimer = scene.time.addEvent({
      delay: 45,
      loop: true,
      callback: () => {
        if (!body.active) return;
        const bp = BASE_PTS[Phaser.Math.Between(0, BASE_PTS.length - 1)];
        const cos = Math.cos(rotRad), sin = Math.sin(rotRad);
        const wx = body.x + bp.x * cos - bp.y * sin;
        const wy = body.y + bp.x * sin + bp.y * cos;
        this.spawnSpark(scene, wx, wy, {
          color: Phaser.Math.Between(0, 1) ? 0xff9900 : 0xffcc44,
          radius: Phaser.Math.FloatBetween(1, 3),
          tx: wx + Phaser.Math.FloatBetween(-12, 12),
          ty: wy + Phaser.Math.FloatBetween(-18, 4),
          duration: Phaser.Math.Between(180, 320),
          endScale: 0.2,
        });
      },
    });
    this.activeTimers.push(particleTimer);

    const hitSet = new Set<Phaser.Physics.Arcade.Sprite>();
    const HIT_RADIUS = R_OUT + 10;

    scene.tweens.add({
      targets: all,
      x: `+=${dx * TRAVEL}`,
      y: `+=${dy * TRAVEL}`,
      duration,
      ease: 'Linear',
      onUpdate: () => {
        const t  = scene.time.now;
        outerGlow.clear();
        outerGlow.fillStyle(0xff5500, 0.22 + Math.sin(t * 0.011) * 0.10);
        outerGlow.fillPoints(this.wavyPoints(_bufs.outer, t, { scale: 1.85, speed: 0.007, amp: 6.0, phase: 0 }), true);

        midGlow.clear();
        midGlow.fillStyle(0xff8800, 0.42 + Math.sin(t * 0.014 + 1.2) * 0.12);
        midGlow.fillPoints(this.wavyPoints(_bufs.mid, t, { scale: 1.32, speed: 0.01, amp: 4.0, phase: 1.0 }), true);

        const bodyPts = this.wavyPoints(_bufs.body, t, { scale: 1.0, speed: 0.013, amp: 2.5, phase: 2.1 });

        body.clear();
        body.fillStyle(0xffcc55, 0.96);
        body.fillPoints(bodyPts, true);

        // body와 동일 파형 → 캐시된 bodyPts 재사용
        edge.clear();
        edge.lineStyle(2, 0xffeecc, 0.9);
        edge.strokePoints(bodyPts, true);

        const cx = body.x, cy = body.y;
        (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[]).forEach(sp => {
          if (!sp.active || hitSet.has(sp)) return;
          if (Phaser.Math.Distance.Between(cx, cy, sp.x, sp.y) <= HIT_RADIUS) {
            hitSet.add(sp);
            for (let i = 0; i < 7; i++) {
              const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
              const dist  = Phaser.Math.Between(10, 28);
              this.spawnSpark(scene, sp.x, sp.y, {
                color: 0xffaa55,
                radius: Phaser.Math.Between(2, 5),
                tx: sp.x + Math.cos(angle) * dist,
                ty: sp.y + Math.sin(angle) * dist - 8,
                duration: Phaser.Math.Between(180, 380),
              });
            }
            (sp as PoolablePoopBase).recycle();
            api.addAbilityBonus(KNIGHT_PARAMS.beamKillBonus);
          }
        });
      },
      onComplete: () => {
        particleTimer.destroy();
        this.activeTimers = this.activeTimers.filter(t => t !== particleTimer);
        all.forEach(g => {
          this.activeGraphics = this.activeGraphics.filter(ag => ag !== g);
          g.destroy();
        });
      },
    });
  }

  private spawnSpark(
    scene: Phaser.Scene,
    x: number, y: number,
    opts: { color: number; radius: number; tx: number; ty: number; duration: number; endScale?: number },
  ): void {
    const g = scene.add.graphics().setDepth(122).setPosition(x, y);
    g.fillStyle(opts.color, 1);
    g.fillCircle(0, 0, opts.radius);
    const tween: Phaser.Types.Tweens.TweenBuilderConfig = {
      targets: g, x: opts.tx, y: opts.ty, alpha: 0,
      duration: opts.duration, ease: 'Quad.easeOut',
      onComplete: () => g.destroy(),
    };
    if (opts.endScale !== undefined) {
      (tween as Record<string, unknown>).scaleX = opts.endScale;
      (tween as Record<string, unknown>).scaleY = opts.endScale;
    }
    scene.tweens.add(tween);
  }
}

import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { SENTINEL_PARAMS } from '../config/abilityParams';

/**
 * 센티넬 (UR) — 보호막
 * ★0: 2개 시작 / 300점마다 충전 / 최대 3  / ★1: 2개 / 250점마다 / 최대 4
 * ★2: 3개 시작 / 200점마다 충전 / 최대 4  / ★3: 3개 / 150점마다 / 최대 5 + 흡수 시 연쇄 전기 3개 추가 제거
 * - UI: 붉은 공이 허리 주변 수평 궤도 공전 + 전기 파지직 (재사용 Graphics)
 */
export class SentinelAbility extends BaseAbility {
  private shieldCount = 0;
  private orbitDroplets: Phaser.GameObjects.Graphics[] = [];
  private orbitAngle = 0;

  // ── 전기 스파크: persistent Graphics 재사용 (동적 생성 없음) ──
  private sparkGfx: Phaser.GameObjects.Graphics | null = null;
  private sparkTween: Phaser.Tweens.Tween | null = null;
  private sparkTimer = 0;

  private static readonly ORBIT_SPEED   = 3.0;
  private static readonly ORBIT_RX      = 26;
  private static readonly ORBIT_RY      = 7;
  private static readonly ORBIT_WAIST_Y = 8;
  private static readonly RED           = 0xff2222;
  private static readonly RED_LIGHT     = 0xff6666;

  override onCreate(api: GameSceneAPI): void {
    this.shieldCount = SENTINEL_PARAMS.startShields;
    this.spawnDroplets(api, SENTINEL_PARAMS.startShields);
    this.sparkGfx = api.scene.add.graphics().setDepth(96).setAlpha(0);
    this.sparkGfx.postFX.addGlow(0xff4444, 7, 0, false, 0.1, 10);
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % SENTINEL_PARAMS.chargeInterval === 0 && this.shieldCount < SENTINEL_PARAMS.maxShields) {
      this.shieldCount++;
      this.playShieldChargeEffect(api);
      this.spawnDroplets(api, 1);
    }
  }

  override onHitPoop(api: GameSceneAPI): boolean {
    if (this.shieldCount > 0) {
      this.shieldCount--;
      this.scatterDroplets(api, 1);
      this.playShieldBreakEffect(api);
      this.zapNearbyPoops(api, 320);
      return true;
    }
    return false;
  }

  override onUpdate(api: GameSceneAPI): void {
    if (this.orbitDroplets.length === 0) return;

    const delta  = api.scene.game.loop.delta / 1000;
    const deltMs = api.scene.game.loop.delta;
    this.orbitAngle += SentinelAbility.ORBIT_SPEED * delta;

    const cx    = api.player.x;
    const cy    = api.player.y + SentinelAbility.ORBIT_WAIST_Y;
    const total = this.orbitDroplets.length;
    const RX    = SentinelAbility.ORBIT_RX;
    const RY    = SentinelAbility.ORBIT_RY;

    this.orbitDroplets.forEach((drop, i) => {
      if (!drop.active) return;
      const angle = this.orbitAngle + (i / total) * Math.PI * 2;
      const sinA  = Math.sin(angle);

      drop.setPosition(cx + Math.cos(angle) * RX, cy + sinA * RY);

      const t = (sinA + 1) / 2;
      drop.setScale(0.55 + 0.55 * t);
      drop.setAlpha(0.35 + 0.65 * t);
      drop.setDepth(sinA > 0 ? 101 : 89);
    });

    // 전기 파지직: 250ms마다 persistent sparkGfx를 clear+redraw
    this.sparkTimer += deltMs;
    if (this.sparkTimer >= 250) {
      this.sparkTimer = 0;
      this.redrawSparks(api);
    }
  }

  // ─────────────────────────────────────────────────────────────
  // 리소스 정리 (게임 오버 시 GameScene에서 호출)
  // ─────────────────────────────────────────────────────────────

  override onDestroy(_api: GameSceneAPI): void {
    this.sparkTween?.stop();
    this.sparkGfx?.destroy();
    this.orbitDroplets.forEach(drop => drop.destroy());
  }

  // ─────────────────────────────────────────────────────────────
  // 전기 스파크 (재사용 Graphics)
  // ─────────────────────────────────────────────────────────────

  /** persistent sparkGfx를 clear 후 몸+공 스파크를 새로 그리고 alpha tween */
  private redrawSparks(api: GameSceneAPI): void {
    const g = this.sparkGfx;
    if (!g?.active) return;

    g.clear();
    g.setAlpha(1);
    this.sparkTween?.stop();

    // 몸 주변 스파크 (굵게)
    const ba    = Phaser.Math.FloatBetween(0, Math.PI * 2);
    const br    = Phaser.Math.FloatBetween(18, 34);
    this.drawSparkLine(g, api.player.x + Math.cos(ba) * br, api.player.y + Math.sin(ba) * br * 0.6, 2.5, 10);

    // 공 주변 스파크 (가늘게, 40% 확률 per droplet)
    this.orbitDroplets.forEach(drop => {
      if (drop.active && drop.alpha > 0.5 && Math.random() < 0.4) {
        this.drawSparkLine(g, drop.x, drop.y, 1, 7);
      }
    });

    this.sparkTween = api.scene.tweens.add({
      targets: g,
      alpha: 0,
      duration: 200,
      ease: 'Quad.easeOut',
    });
  }

  /** 전달받은 Graphics에 지그재그 라인을 직접 그림 (새 객체 생성 없음) */
  private drawSparkLine(g: Phaser.GameObjects.Graphics, ox: number, oy: number, thickness: number, segLen: number): void {
    const color = Math.random() < 0.6 ? 0xff3333 : 0xff7744;
    g.lineStyle(thickness, color, 1);
    g.beginPath();
    let px = ox + Phaser.Math.Between(-5, 5);
    let py = oy + Phaser.Math.Between(-5, 5);
    g.moveTo(px, py);
    const segs = Phaser.Math.Between(2, 4);
    for (let j = 0; j < segs; j++) {
      px += Phaser.Math.Between(-segLen, segLen);
      py += Phaser.Math.Between(-segLen, segLen);
      g.lineTo(px, py);
    }
    g.strokePath();
  }

  // ─────────────────────────────────────────────────────────────
  // 방울 관리
  // ─────────────────────────────────────────────────────────────

  private spawnDroplets(api: GameSceneAPI, count: number): void {
    const scene = api.scene;
    for (let i = 0; i < count; i++) {
      const g = scene.add.graphics().setDepth(95);
      this.drawDroplet(g);
      g.setPosition(api.player.x, api.player.y + SentinelAbility.ORBIT_WAIST_Y);
      g.setAlpha(0);
      g.postFX.addGlow(SentinelAbility.RED, 10, 0, false, 0.1, 14);
      this.orbitDroplets.push(g);
      scene.tweens.add({ targets: g, alpha: 1, scaleX: 1, scaleY: 1, duration: 350, delay: i * 50, ease: 'Back.easeOut' });
    }
  }

  private scatterDroplets(api: GameSceneAPI, count: number): void {
    const scene   = api.scene;
    const removed = this.orbitDroplets.splice(0, count);
    removed.forEach(drop => {
      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
      const dist  = Phaser.Math.FloatBetween(30, 55);
      scene.tweens.add({
        targets: drop,
        x: drop.x + Math.cos(angle) * dist,
        y: drop.y + Math.sin(angle) * dist,
        alpha: 0, scaleX: 0.1, scaleY: 0.1,
        duration: 120, ease: 'Quad.easeIn',
        onComplete: () => drop.destroy(),
      });
    });
  }

  private drawDroplet(g: Phaser.GameObjects.Graphics): void {
    g.clear();
    g.fillStyle(SentinelAbility.RED, 0.22);
    g.fillCircle(0, 0, 15);
    g.fillStyle(SentinelAbility.RED, 0.4);
    g.fillCircle(0, 0, 10);
    g.fillStyle(SentinelAbility.RED, 0.95);
    g.fillCircle(0, 0, 7);
    g.fillStyle(0xffffff, 0.5);
    g.fillCircle(-2, -2.5, 2.5);
  }

  // ─────────────────────────────────────────────────────────────
  // 파장 범위 내 똥 제거
  // ─────────────────────────────────────────────────────────────

  private zapNearbyPoops(api: GameSceneAPI, radius: number): void {
    const cx = api.player.x;
    const cy = api.player.y;
    const r2 = radius * radius;

    const targets = (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active && (p.x - cx) ** 2 + (p.y - cy) ** 2 <= r2);

    if (targets.length === 0) return;

    const positions = targets.map(p => ({ x: p.x, y: p.y }));
    targets.forEach(p => (p as PoolablePoopBase).recycle());

    // 단일 Graphics에 모든 위치 그리기 → 3회 redraw로 지글 효과
    const zapG = api.scene.add.graphics().setDepth(155);
    let frame   = 0;

    const drawZapFrame = () => {
      zapG.clear();
      positions.forEach(pos => {
        zapG.fillStyle(SentinelAbility.RED, 0.55 - frame * 0.12);
        zapG.fillCircle(pos.x, pos.y, 10);
