        targets: dot, y: cy - Phaser.Math.Between(28, 56), alpha: 0,
        duration: Phaser.Math.Between(340, 530), delay: i * 40, ease: 'Quad.easeOut',
        onComplete: () => dot.destroy(),
      });
    }
  }
}

